-- ════════════════════════════════════════════════════════════════════════
-- Las 8 zonas de cambaceo de la ciudad de Aguascalientes.
--
-- Cada zona esta balanceada al mismo numero de negocios objetivo (~4,085),
-- que es lo que una celula de 5 vendedores recorre en un mes.
-- Los limites siguen donde estan los negocios, no las calles: se ajustan
-- en campo cuando una avenida o un arroyo parte un sector.
--
-- "priority" es el orden sugerido de ataque: primero donde hay mas
-- negocios por km2, porque se camina menos entre venta y venta.
-- ════════════════════════════════════════════════════════════════════════

-- Fuera los cuadrantes provisionales que se cargaron antes de tener esto
update public.businesses set zone_id = null
 where zone_id in (select id from public.zones where name like 'Capital %');
delete from public.zones where name like 'Capital %';

